      await safeDirectory(destination);
      const current = await inspectInstalled(destination);
      if (JSON.stringify(current) !== JSON.stringify(target.old)) fail(`Installation changed during setup: ${destination}`);
      const id = randomUUID();
      let backup = null;
      let stage = null;
